export interface DsBadgeAttributes {
  /** Defaults to `"default"`. */
  variant?: BadgeVariant;
}

export interface DsButtonAttributes {
  /** Defaults to `"primary"`. */
  variant?: ButtonVariant;
  /** Defaults to `"md"`. */
  size?: ButtonSize;
  /** Defaults to `"button"`. */
  type?: ButtonType;
  disabled?: boolean;
  /** Fills the available inline size. */
  "full-width"?: boolean;
}

export interface DsCheckboxAttributes {
  /** Visible label. This is the accessible name. */
  label?: string;
  /** Supporting guidance. Included in the accessible description when set. */
  hint?: string;
  /** What to fix. A non-empty value marks the control invalid and is included in the accessible description. */
  error?: string;
  /** Whether the option is on. The attribute sets the initial state; form reset restores it. */
  checked?: boolean;
  /** Shows a mixed state, for a parent whose options are partly selected. Presentational only; it does not change the submitted value. */
  indeterminate?: boolean;
  /** Form field name. The value is submitted under this name when checked. */
  name?: string;
  /** Value submitted when checked. Defaults to "on", as for a native checkbox. */
  value?: string;
  /** Prevents toggling. A disabled checkbox does not submit its value. */
  disabled?: boolean;
  /** The checkbox must be checked before submit. Conveyed by more than color. */
  required?: boolean;
}

export interface DsDialogAttributes {
  open?: boolean;
  label?: string;
  description?: string;
  /** Defaults to true. Use "false" to block Escape dismissal. */
  dismissible?: boolean | "true" | "false";
}

export interface DsIconAttributes {
  /** What the graphic means. Without it the icon is decorative and hidden from assistive technology. */
  label?: string;
  /** Defaults to `"inherit"`, the surrounding text size. */
  size?: IconSize;
}

export interface DsLinkAttributes {
  /** Destination. Without it the control is not a link and cannot receive focus. */
  href?: string;
  /** Defaults to `"inline"`. */
  variant?: LinkVariant;
}

export interface DsRadioGroupAttributes {
  label?: string;
  hint?: string;
  error?: string;
  name?: string;
  value?: string;
  disabled?: boolean;
  required?: boolean;
}

